import pathlib,re,sys;bad=[];
for p in pathlib.Path('node/exitnode/watchdog').rglob('*.py'):
    t=p.read_text(encoding='utf-8')
    for m in re.finditer(r'"systemctl",\s*"(restart|stop|start|disable|enable)",\s*"([^"]+)"',t):
        if not m.group(2).startswith('exitnode-'): bad.append(str(p)+':'+m.group(0))
    if re.search(r'"(shutdown|poweroff|halt)"',t): bad.append(str(p)+':shutdown')
print(bad);sys.exit(1 if bad else 0)
